import{_ as o,l as n,o as t,c as s,v as e,p as l,x as i,d as m,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const H=JSON.parse('{"title":"HMM 隐马尔可夫体制","description":"","frontmatter":{"title":"HMM 隐马尔可夫体制","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hmm-regime.md","filePath":"quant/hmm-regime.md","lastUpdated":1789023840000}'),E={name:"quant/hmm-regime.md"};function d(B,a,c,_,u,A){const r=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="hmm-隐马尔可夫体制" tabindex="-1">HMM 隐马尔可夫体制 <a class="header-anchor" href="#hmm-隐马尔可夫体制" aria-label="Permalink to &quot;HMM 隐马尔可夫体制&quot;">​</a></h1><div class="epigraph"><p>把观测写成由一条不可见的有限状态马尔可夫链切换参数的条件分布，滤波给出「现在处于哪一体制」的概率；状态会按转移矩阵回来，这与一次性结构断裂不是同一类过程。</p><footer>—— Hamilton, A New Approach to the Economic Analysis of Nonstationary Time Series and the Business Cycle, Econometrica, 1989</footer></div><p><a href="/quant/regime-switching-premia">体制切换</a> 把 Hamilton 装置接到溢价与配置：风险价格随离散状态变。本篇把同一套隐马尔可夫模型（HMM）接到<strong>价差动力学</strong>：均值、回复速度与扩散可以分体制，滤波概率进入是否开仓、开多大。它补的是 <a href="/quant/ou-spread">OU 残差</a> 的常参数假设，以及 <a href="/quant/gregory-hansen">Gregory–Hansen</a> / <a href="/quant/bai-perron">Bai–Perron</a> 的「换了就不自动回来」。Hamilton（1989）的产出模型是均值切换；配对里更常是方差切换或「回复/随机游走」两体制。本篇写 Hamilton 滤波与 Kim 平滑、识别来自持续性，以及平滑概率为何不能进回测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常参数 OU 假定 \\(\\kappa,\\mu,\\sigma\\) 不变。真实价差常在「快回归的平静段」与「几乎不回归的动荡段」之间切换：危机里相关向 1 塌缩，残差波动变大，\\(\\hat\\kappa\\) 被估短或估乱。若用全样本 OU 定阈值，平静期交易过密，动荡期阈值又不够。HMM 把观测密度写成</p> \\[z_t\\mid s_t \\sim p(\\,\\cdot\\mid \\theta_{s_t}),\\qquad P(s_t=j\\mid s_{t-1}=i)=p_{ij}, \\]<p>\\(s_t\\in\\{1,\\ldots,K\\}\\) 不可观测。要估的是各体制的 \\(\\theta_k\\)、转移矩阵，以及 \\(P(s_t\\mid \\mathcal{F}_t)\\)。问题是：\\(K\\) 无法从理论唯一钉死，且部分参数在「某体制概率为零」的原假设下不可识别，似然比不规则。</p><p>一次性协整破裂是另一 DGP：新 \\(\\beta\\) 可能永久有效，转移矩阵里 \\(p_{21}\\gt 0\\) 会错误地承诺回到旧均衡。选 HMM 还是 GH/BP，是经济判断：指数权重、会计口径更像台阶；波动的牛熊更像来回链。不能只看样本内似然。</p><h3 id="体制个数与标签" tabindex="-1">体制个数与标签 <a class="header-anchor" href="#体制个数与标签" aria-label="Permalink to &quot;体制个数与标签&quot;">​</a></h3><p>\\(K=2\\) 常被标成低波动/高波动或回复/单位根。\\(K=3\\) 有时分出崩溃。信息准则在 HMM 里不可靠。Hamilton 强调体制是描述装置，不等于 NBER 标签，更不等于买卖信号。约束应来自：各体制期望持续期是否像「一段时期」而不是「一个跳」；滤波概率是否与危机日期大致对齐；把两体制均值（或 \\(\\kappa\\)）设成相等后似然掉多少。单凭某日暴跌被标成体制 2，不能说明价差进入了新的可交易状态。</p><p><span class="marginnote">平滑概率 \\(P(s_t\\mid\\mathcal{F}_T)\\) 用了未来观测，适合写经济史。交易、仓位与回测只能用滤波 \\(P(s_t\\mid\\mathcal{F}_t)\\) 或一步预测 \\(P(s_{t+1}\\mid\\mathcal{F}_t)\\)。用平滑阴影去证明「只在体制 1 开仓夏普很高」，是全样本标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>Hamilton 滤波。</strong> 由上一期体制概率经转移矩阵得预测概率，再用当期条件密度更新。高斯切换均值–方差下，这是有限混合的贝叶斯更新。估计用极大似然；EM（Baum–Welch）在独立混合时标准，含马尔可夫依赖时用 Hamilton 的迭代。波动持续很高时，可让各体制带自己的 AR 或把 \\(\\kappa\\) 写成体制依赖：体制 1 为 OU，体制 2 为 \\(\\kappa\\approx 0\\) 的局部鞅。后者直接对应「协整暂时失效」的来回版，与 GH 的永久台阶对照。</p><p><strong>Kim 平滑与 Viterbi。</strong> 平滑给出事后状态，用于诊断与论文配图，不用于下单。Viterbi 给出最可能的整条状态路径，同样是 \\(\\mathcal{F}_T\\) 对象。工程上若需要「当前最可能体制」的点估计，应对滤波概率取阈值（例如 \\(P(s_t=1\\mid\\mathcal{F}_t)\\gt 0.8\\) 才允许按平静 OU 开仓），并承认阈值是又一个设定。</p><p><strong>与可观测协变量。</strong> 转移概率可写成 logistic 于已实现波动、价差绝对值、宏观利差（Filardo 型）。状态仍是潜变量，协变量只调持续期。这比把「VIX 高就停配对」更结构化，但也多了一层过拟合：协变量若含同期价差，等于用要交易的对象去定义能不能交易。</p><h3 id="诊断-持续性、残差、与断裂检验对照" tabindex="-1">诊断：持续性、残差、与断裂检验对照 <a class="header-anchor" href="#诊断-持续性、残差、与断裂检验对照" aria-label="Permalink to &quot;诊断：持续性、残差、与断裂检验对照&quot;">​</a></h3><p>报告 \\(1/(1-p_{ii})\\) 作为期望持续期。若高波动体制平均只持续一两天，模型多半在拟合跳跃，应改跳扩散或把跳跃从残差里分开，而不是用体制溢价去讲商业周期。滤波新息应接近条件白噪声；若仍有单位根，状态维数不够（缺了 \\(\\beta\\) 漂移，应变 Kalman，或承认协整已破）。把 HMM 的 \\(K=2\\) 与 GH 同样本对照：若滤波在某个日期附近把概率从 1 推到 2 且之后长期不回来，DGP 更像台阶，应改 BP/GH，而不是提高 \\(p_{22}\\) 硬撑。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>统计层：混合分布同时产生肥尾与波动聚集——在高 \\(\\sigma\\) 体制多待几天，样本峰度上升，无需单独 \\(t\\) 分布。对 OU，体制依赖的 \\(\\kappa\\) 意味着半衰期是随机的：无条件「平均半衰期」不是任何一种可实现持有期。交易若按无条件 \\(\\kappa\\) 定时间止损，会在慢体制里系统性抱太久。</p><p>经济层：共同因子主导时，残差的短期相关结构变，看起来像 \\(\\kappa\\) 下降；流动性枯竭时 \\(\\sigma\\) 上升。HMM 并不识别是因子还是流动性，只是把观测分段。定价含义与溢价一文相同：若你用滤波概率调仓，交易的是收益自身反推的状态，内生性强，换手会跟着波动走。把 \\(P(s_t=1)\\) 当 alpha 信号，需要额外证据表明该概率在价差之外仍有预测内容，否则只是波动追随。</p><p><span class="marginnote">两个体制的无条件均值是稳态概率加权，不是样本日数加权。用「滤波概率小于 0.5 的日子」去算体制 1 的夏普，既不是 \\(\\mu_1\\)，也不是可实现规则。对象必须写清：模型参数、滤波规则下的实现，还是平滑叙事。</span></p><h3 id="与门限、cusum-的差别" tabindex="-1">与门限、CUSUM 的差别 <a class="header-anchor" href="#与门限、cusum-的差别" aria-label="Permalink to &quot;与门限、CUSUM 的差别&quot;">​</a></h3><p><a href="/quant/threshold-cointegration">门限协整</a> 用可观测的价差穿越阈值来切换调整速度，状态不是潜的。HMM 允许宏观「看起来还好」时，收益自身把概率推向危机体制。CUSUM 不估计回来的概率，只检测偏离恒定参数。<a href="/quant/ou-optimal-stopping">最优停时</a> 通常在单一 OU 下解障碍；体制切换时，最优规则应依赖滤波概率，障碍在高 \\(\\sigma\\) 体制更宽或干脆不开。把常参数障碍套在 HMM 残差上，等于忽略了状态。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>似然多峰、对初值敏感。应多组初值，并约束 \\(p_{ii}\\) 不要估到 1（退化成一次断裂却没有断裂检验的理论）。\\(K\\) 不要用交易期 PnL 去选。不要在滤波概率上再套一层机器学习来「提高夏普」而不把该层纳入多重检验。</p><p>不要用平滑状态画「当时该开仓」。不要把 HMM 的体制 2 自动解释成可做空波动或可做多危机 alpha——价差模型没有给这些资产定价。A 股停牌造成的零收益序列会被当成低波动体制，必须把停牌标成缺失观测。</p><p><span class="marginnote">Hamilton（1989）的渐近是正确设定、平稳遍历链、足够的体制内样本。日频金融很难同时满足。把滤波概率当「做市许可」是把描述装置当成了策略评价。</span></p>',27)),(t(),l(h,null,{default:i(()=>[p(r,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E4%BB%B7%E5%B7%AE%20%2F%20%E6%AE%8B%E5%B7%AE%20z%22%5D%20--%3E%20HMM%5B%22K%20%E4%BD%93%E5%88%B6%E6%9D%A1%E4%BB%B6%E5%AF%86%E5%BA%A6%22%5D%0A%20%20HMM%20--%3E%20FIL%5B%22Hamilton%20%E6%BB%A4%E6%B3%A2%20P(s_t%20%7C%20F_t)%22%5D%0A%20%20FIL%20--%3E%20GATE%5B%22%E4%BB%85%E5%9C%A8%E5%B9%B3%E9%9D%99%E4%BD%93%E5%88%B6%E5%85%81%E8%AE%B8%E5%BC%80%E4%BB%93%22%5D%0A%20%20GATE%20--%3E%20OU%5B%22%E8%AF%A5%E4%BD%93%E5%88%B6%E7%9A%84%20%CE%BA%2C%20%CF%83%20%E5%AE%9A%E9%98%88%E5%80%BC%22%5D%0A%20%20FIL%20--%3E%20SM%5B%22%E5%B9%B3%E6%BB%91%E6%A6%82%E7%8E%87%20%E4%BB%85%E8%AF%8A%E6%96%AD%22%5D%0A%20%20Z%20--%3E%20GH%5B%22%E8%8B%A5%E6%A6%82%E7%8E%87%E4%B8%80%E5%8E%BB%E4%B8%8D%E5%9B%9E%22%5D%0A%20%20GH%20--%3E%20BRK%5B%22%E6%94%B9%20GH%20%2F%20Bai-Perron%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HMM 用隐马尔可夫链切换价差的均值、\\(\\kappa\\) 或 \\(\\sigma\\)；Hamilton 滤波给出时点 \\(t\\) 可用的体制概率，状态按转移矩阵有正概率回来。</li><li>这与 Gregory–Hansen / Bai–Perron 的台阶型断裂不同；用错会给出虚假回归概率或切碎样本。</li><li>回测只能用滤波或一步预测概率，不能用 Kim 平滑或 Viterbi 路径。</li><li>持续性过短说明模型在拟合跳跃；无条件半衰期在切换 \\(\\kappa\\) 下没有交易含义。</li><li>门限模型用可观测阈值切换；HMM 的状态不可观测，换手易变成波动追随。</li><li>出处：Hamilton, <em>Econometrica</em>, 1989；平滑见 Kim, <em>Journal of Econometrics</em>, 1994；体制切换溢价的配置含义见 Ang and Bekaert 及 Guidolin and Timmermann。</li></ul>',2))])}const g=o(E,[["render",d]]);export{H as __pageData,g as default};
